<section id="ground-panel" class="ground-panel" aria-label="Observer perspective sky">
  <div class="ground-heading"><div><h3>Ground sky</h3></div><span class="ground-badge">360° sky · horizon transparent</span></div>
  <div class="constellation-controls">
    <div class="constellation-select-row"><label for="ground-tradition">Constellation tradition <select id="ground-tradition" aria-describedby="ground-tradition-note"><option value="none">Loading traditions…</option></select></label><label class="constellation-label-toggle"><input id="ground-constellation-labels" type="checkbox" checked> Figure names</label></div>
    <p id="ground-tradition-note" aria-live="polite"></p>
    <div class="constellation-links"><a id="ground-tradition-source" href="https://github.com/Stellarium/stellarium" target="_blank" rel="noopener">Tradition source ↗</a><button id="constellation-sources" class="text-button">Credits &amp; method</button><a href="resources/constellations.json" download>Constellation dataset ↓</a><a href="resources/constellation-sources.zip" download>Source files ↓</a></div>
    <div class="constellation-finder"><label for="ground-figure">Find a figure <select id="ground-figure" aria-describedby="ground-figure-note"><option value="">Choose a figure…</option></select></label><span>Turns the view toward the figure.</span></div>
    <div id="ground-figure-note" class="figure-evidence" aria-live="polite" hidden></div>
    <details id="ground-tradition-evidence" class="tradition-evidence" hidden><summary>About this reconstruction &amp; unresolved names</summary><div id="ground-tradition-evidence-body"></div></details>
  </div>
  <div class="ground-stage"><canvas id="ground-canvas" tabindex="0" aria-label="Interactive observer sky. Drag to look around; scroll to zoom. Arrow keys look, plus and minus zoom, Home resets." aria-describedby="ground-help">This interactive sky requires a browser with Canvas support.</canvas><div class="ground-readout" aria-hidden="true"><span id="ground-bearing">S · 180°</span><span id="ground-elevation">Looking up 20°</span><span id="ground-field">100° field</span></div></div>
  <div class="ground-toolbar"><div class="ground-directions" role="group" aria-label="Look direction"><button data-look="0" class="small-button" aria-label="Look north">N</button><button data-look="90" class="small-button" aria-label="Look east">E</button><button data-look="180" class="small-button" aria-label="Look south">S</button><button data-look="270" class="small-button" aria-label="Look west">W</button><button data-look="up" class="small-button">Up</button><button data-look="down" class="small-button">Down</button></div><button id="ground-reset" class="small-button">Reset view</button><button id="ground-focus" class="small-button">Find selected</button></div>
  <div class="ground-settings"><label for="ground-fov">Field of view <input id="ground-fov" type="range" min="25" max="120" value="100" step="1"><output id="ground-fov-value">100°</output></label><label><input id="ground-grid" type="checkbox"> Altitude / azimuth grid</label></div>
  <p id="ground-help" class="ground-help">Drag to look around · Scroll to zoom · Click a star to inspect it. The mint line is your horizon. Stars and figures beneath it remain plotted, dimmed for reference. Figure lines remain visible as you change the star brightness cutoff.</p>
</section>
